    @model_validator(mode="after")
    def validate_multi_part_fields(self) -> "ContractNoticeCoreRawV1":
        """Multi-part-only fields can be present only when section 4.1.9 indicates >1 parts."""
        if self._has_text(self.cn_section_4_1_9):
            parts_count_self = self._extract_parts_count(self.cn_section_4_1_9)
            if parts_count_self is None or parts_count_self <= 1:
                raise ValueError(
                    "cn_section_4_1_9 is present but does not indicate multi-part (>1): "
                    f"cn_section_4_1_9={self.cn_section_4_1_9!r}"
                )

        parts_count = self._extract_parts_count(self.cn_section_4_1_9)
        is_multi_part = parts_count is not None and parts_count > 1

        multi_only_fields = {
            "cn_section_4_1_10": self.cn_section_4_1_10,
            "cn_section_4_1_11": self.cn_section_4_1_11,
            "cn_section_4_1_12": self.cn_section_4_1_12,
            "cn_section_4_2_5": self.cn_section_4_2_5,
        }
        present_multi_only = [name for name, value in multi_only_fields.items() if self._has_text(value)]

        if present_multi_only and not is_multi_part:
            raise ValueError(
                "Fields valid only for multi-part ContractNotice are present while cn_section_4_1_9 "
                f"does not indicate multi-part (>1). offending_fields={present_multi_only}, "
                f"cn_section_4_1_9={self.cn_section_4_1_9!r}"
            )
        return self

    @staticmethod
    def _extract_parts_count(value: str | None) -> int | None:
        if value is None:
            return None
        match = re.search(r"\d+", value)
        if not match:
            return None
        try:
            return int(match.group(0))
        except ValueError:
            return None

    @staticmethod
    def _has_text(value: str | None) -> bool:
        return value is not None and value.strip() != ""




